import {Game} from './engine.js';import {Renderer} from './render.js';import {Sound} from './audio.js';import {C,facilityTypes as F,traits,upgrades,waveDefinitions as W,weatherEffects} from './config.js';
const $=s=>document.querySelector(s),game=new Game(),renderer=new Renderer($('#game'));const KEY='recycle-oni-v01';let saved={profit:0,avoid:0,flow:0,rank:'C',muted:true};try{Object.assign(saved,JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{}const sound=new Sound(saved.muted);let lastState='',selected=null,mode=null,last=0,hudTimer=0,savedResult=false;function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved))}catch{}}
function btn(text,fn,cls='',disabled=false){const b=document.createElement('button');b.textContent=text;b.className=cls;b.disabled=disabled;b.onclick=fn;return b}function say(t){$('#caption').textContent=`鬼 「${t}」`}function refresh(){lastState='';ui()}
function ui(){const state=game.state;if(lastState===state)return;lastState=state;const ov=$('#overlay'),ctl=$('#controls');ov.replaceChildren();ctl.replaceChildren();$('#detail').replaceChildren();selected=null;mode=null;if(state==='title'){ov.innerHTML=`<div class="panel"><div class="eyebrow">RECYCLE ONI / v0.1</div><h1>リサイクルの鬼</h1><p>「まだ使える。」<br>小鬼と施設を配置して、8回の回収日を乗り切れ。</p><div class="steps"><span>01 道路から救出</span><span>02 運んで処理</span><span>03 利益で現場を強化</span></div><p>近くに置く。得意を任せる。焼却を減らす。</p><div id="start-slot"></div><p>BEST ¥${saved.profit.toLocaleString()} · 回避 ${Math.round(saved.avoid*100)}% · FLOW ${saved.flow} · ${saved.rank}</p></div>`;$('#start-slot').append(btn('現場に入る →',()=>{sound.init();game.prepare();refresh()},'primary'));say('まだ使える。');return}
 if(state==='upgrade'){ov.innerHTML=`<div class="panel"><div class="eyebrow">WAVE ${game.wave} COMPLETE</div><h2>次の現場を、もっと強く。</h2><p>利益 +¥${game.summary.profit} ／ 焼却回避 ${Math.round(game.summary.avoid*100)}%</p><div class="cards"></div><p>次：${W[game.wave].name} — ${W[game.wave].hint}</p></div>`;for(const u of game.choices){let b=btn('',()=>{game.choose(u.id);refresh()});b.innerHTML=`<strong>${u.name}</strong><small>${u.desc}</small>`;$('.cards').append(b)}return}
 if(state==='result'){if(!savedResult){savedResult=true;saved.profit=Math.max(saved.profit,game.profit);saved.avoid=Math.max(saved.avoid,game.rescued/Math.max(1,game.total));saved.flow=Math.max(saved.flow,game.maxFlow);saved.rank=['S','A','B','C'][Math.min(['S','A','B','C'].indexOf(saved.rank),['S','A','B','C'].indexOf(game.rank))];persist()}ov.innerHTML=`<div class="panel"><span class="rank">${game.rank}</span><div class="eyebrow">${game.clear?'ALL 8 WAVES CLEAR':'RUN FINISHED'}</div><h2>${game.clear?'……よし。':'小鬼たちは、ひと休み。'}</h2><p>${game.clear?'まだ使えるものを、まちへ戻した。':'大鬼は、静かに空を見上げた。'}</p><div class="stats"><div>TOTAL PROFIT<b>¥${game.profit.toLocaleString()}</b></div><div>焼却回避率<b>${Math.round(game.rescued/Math.max(1,game.total)*100)}%</b></div><div>最終 地球の熱<b>${game.heat.toFixed(1)} / 100</b></div><div>最大 ONI FLOW<b>×${game.maxFlow}</b></div><div>救出したゴミ<b>${game.rescued} 個</b></div></div><div id="replay"></div></div>`;$('#replay').append(btn('もう一度遊ぶ',()=>{game.reset();savedResult=false;refresh()},'primary'));return}
 if(state==='prep'){let hint=document.createElement('span');hint.className='hint';hint.textContent=`次：${W[game.wave].name} ｜ ${W[game.wave].hint}`;ctl.append(hint);for(const [type,f]of Object.entries(F))ctl.append(btn(`${f.name} ¥${f.price}`,()=>{mode={type};say('空きマスを選べ。');$('#detail').replaceChildren()},'',game.money<f.price||game.facilities.length>=C.maxFacilities));ctl.append(btn(`小鬼 + ¥${C.oniPrice}`,()=>{game.recruit();refresh()},'',game.money<C.oniPrice||game.onis.length>=C.maxOni));ctl.append(btn(`土地 ¥${C.landPrice}`,()=>{game.expand();refresh()},'',game.land===14||game.money<C.landPrice));ctl.append(btn(`Wave ${game.wave+1} 開始 →`,()=>{sound.init();game.startWave();refresh()},'primary'));say(game.wave===0?'施設・小鬼をタップで確認。準備ができたら開始。':'配置を整えろ。まだ使える。')}
 if(state==='wave'){ctl.append(btn('👹 まだ使える！',()=>{if(game.command())refresh()},'primary',game.shoutUsed));const h=document.createElement('span');h.className='hint';h.textContent='号令：1Waveに1回、6秒間加速。小鬼・施設はタップで確認。';ctl.append(h);say('まだ使える。')}
 if(Object.keys(game.buffs).length){let chips=document.createElement('div');chips.className='chips';for(const [id,n]of Object.entries(game.buffs)){let s=document.createElement('span');s.textContent=upgrades.find(u=>u.id===id).name+(n>1?` ×${n}`:'');chips.append(s)}ctl.append(chips)}}
function detail(){const d=$('#detail');d.replaceChildren();if(!selected)return;if(selected.kind==='facility'){const f=game.facilities.find(f=>f.id===selected.id);d.innerHTML=`<b>${F[f.type].name} Lv.${f.level}</b><p>担当 ${game.onis.filter(o=>o.facility===f.id).length}体 ／ 入力 ${f.input.length}/${game.capacity(f)}<br>処理中 ${f.jobs.length} ／ 次工程待ち ${f.output.length}<br>${game.synergy(f)>1?'隣接連携：処理 +10%':'近い施設ほど運搬が速い'}</p>`;if(game.state==='prep'){d.append(btn('施設を移動',()=>{mode={move:f.id};say('移動先の空きマスを選べ。')}));d.append(btn(`Lv.UP ¥${C.levelPrice*f.level}`,()=>{game.level(f.id);refresh()},'',game.money<C.levelPrice*f.level||f.level>=4))}}else{const o=game.onis.find(o=>o.id===selected.id),f=game.facilities.find(f=>f.id===o.facility);d.innerHTML=`<b>小鬼 #${o.id}</b><p>得意：${F[o.type].name}（作業 +25%）<br>${traits[o.trait].name}：${traits[o.trait].desc}<br>体力 ${Math.round(o.stamina)}/${o.max}<br>担当：${F[f.type].name} #${f.id}</p>`;if(game.state==='prep'){const label=document.createElement('label');label.textContent='担当変更';const select=document.createElement('select');select.setAttribute('aria-label','小鬼の担当施設');for(const f of game.facilities){let option=document.createElement('option');option.value=f.id;option.textContent=`${F[f.type].name} #${f.id}${f.type===o.type?' ★得意':''}`;option.selected=f.id===o.facility;select.append(option)}select.onchange=()=>{game.assign(o.id,+select.value);detail()};label.append(select);d.append(label)}}d.append(btn('閉じる',()=>{selected=null;d.replaceChildren()}))}
$('#game').addEventListener('pointerdown',e=>{if(!['prep','wave'].includes(game.state))return;const p=renderer.point(e);if(mode&&game.state==='prep'){let ok=mode.move?game.move(mode.move,p.x,p.y):game.build(mode.type,p.x,p.y);if(ok){refresh();say('……よし。')}else say('資金・空き地・入口を確認。別のマスを選べ。');return}const o=game.onis.find(o=>Math.hypot(o.x-p.x,o.y-p.y)<.85),f=game.facilities.find(f=>p.x>=f.x&&p.x<f.x+2&&p.y>=f.y&&p.y<f.y+2);selected=o?{kind:'oni',id:o.id}:f?{kind:'facility',id:f.id}:null;detail()});
$('#mute').onclick=()=>{sound.init();sound.muted=!sound.muted;saved.muted=sound.muted;persist();$('#mute').textContent=sound.muted?'音 OFF':'音 ON'};$('#mute').textContent=sound.muted?'音 OFF':'音 ON';document.addEventListener('visibilitychange',()=>{last=performance.now()});
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(!document.hidden)game.tick(dt);sound.tick(dt,game.state==='wave');while(game.events.length){const e=game.events.shift();sound.effect(e.kind);if(['shout','flow','reuse','burn'].includes(e.kind))say(e.kind==='burn'?'……。':e.text)}ui();renderer.draw(game,selected,mode);hudTimer+=dt;if(hudTimer>.15){hudTimer=0;$('#hud').innerHTML=`<div>WAVE <b>${Math.max(1,game.wave)}/8</b></div><div>資金 <b>¥${game.money.toLocaleString()}</b></div><div>地球の熱 <b>${Math.floor(game.heat)}</b><meter min="0" max="100" low="25" high="75" optimum="0" value="${game.heat}"></meter></div><div>FLOW <b>×${Math.floor(game.flow)}</b></div><div>${game.state==='wave'?`${weatherEffects[game.weather].name} · ${Math.max(0,Math.ceil(C.duration-game.time))}秒`:'準備で現場を最適化'}</div>`}requestAnimationFrame(frame)}ui();requestAnimationFrame(frame);
